#!/usr/bin/env bash
set -Eeuo pipefail
role=preflight; server="${LINKSEND_SERVER:-}"; stun="${LINKSEND_STUN:-}"; bind="${LINKSEND_BIND:-}"; data_dir="${LINKSEND_DATA_DIR:-.stage2a/profile}"; receive_dir="${LINKSEND_RECEIVE_DIR:-}"; peer="${LINKSEND_PEER:-}"; binary="${LINKSEND_BINARY:-}"; skip=0; files=()
while (($#)); do case "$1" in --role) role="$2";shift 2;;--server) server="$2";shift 2;;--stun) stun="$2";shift 2;;--bind) bind="$2";shift 2;;--data-dir) data_dir="$2";shift 2;;--receive-dir) receive_dir="$2";shift 2;;--peer) peer="$2";shift 2;;--binary) binary="$2";shift 2;;--skip-build) skip=1;shift;;--) shift;files=("$@");break;;*) echo "未知参数: $1" >&2;exit 2;;esac;done
[[ "$role" =~ ^(preflight|receiver|sender)$ ]]||{ echo '非法 role' >&2;exit 2; }; [[ -n "$server" ]]||{ echo '请提供 --server' >&2;exit 2; }; [[ "$server" != *127.0.0.1* && "$server" != *localhost* ]]||{ echo '禁止 loopback 信令地址' >&2;exit 2; }; cd "$(dirname "$0")/.."; stamp=$(date +%Y%m%d-%H%M%S); evidence=".stage2a/$stamp"; mkdir -p "$evidence" "$data_dir"; command -v go >/dev/null||{ echo '未找到 Go' >&2;exit 1; }; go version >"$evidence/go-version.log"; host=$(python3 -c 'import urllib.parse,sys;print(urllib.parse.urlparse(sys.argv[1]).hostname)' "$server"); getent hosts "$host" >"$evidence/dns.log" 2>&1 || true
if ((skip)); then [[ -n "$binary" && -x "$binary" ]]||{ echo '--skip-build 必须提供可执行 --binary' >&2;exit 2; }; else go build -trimpath -o "$evidence/linksend" ./cmd/linksend >"$evidence/build.log" 2>&1; binary="$evidence/linksend"; fi
sha256sum "$binary" >"$evidence/binary.sha256"; printf '{"role":"%s","server":"%s","started":"%s"}\n' "$role" "$server" "$(date -u +%Y-%m-%dT%H:%M:%SZ)" >"$evidence/run.json"; [[ "$role" == preflight ]]&&exit 0; [[ -n "$bind" ]]||{ echo '必须提供 --bind' >&2;exit 2; }; common=(--server "$server" --data-dir "$data_dir"); if [[ "$role" == receiver ]]; then "$binary" "${common[@]}" receive --dir "$receive_dir" --bind "$bind" --stun "$stun" --evidence --auto-accept --wait-timeout 30m >"$evidence/result.json" 2>"$evidence/stderr.log"; else "$binary" "${common[@]}" send --peer "$peer" --bind "$bind" --stun "$stun" --evidence "${files[@]}" >"$evidence/result.json" 2>"$evidence/stderr.log"; fi
